// Checkout conversion module - tracks paid events from checkout completion
const fs = require('fs');
const path = require('path');

const CONVERSION_LOG = path.join(__dirname, '..', 'data', 'conversion_events.log');

function ensureLogFile() {
  const dir = path.dirname(CONVERSION_LOG);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  if (!fs.existsSync(CONVERSION_LOG)) {
    fs.writeFileSync(CONVERSION_LOG, '');
  }
}

function logConversion(event) {
  ensureLogFile();
  const entry = {
    timestamp: new Date().toISOString(),
    event: event,
    paid: true
  };
  fs.appendFileSync(CONVERSION_LOG, JSON.stringify(entry) + '\n');
  return entry;
}

function getConversionCount() {
  ensureLogFile();
  const data = fs.readFileSync(CONVERSION_LOG, 'utf-8').trim();
  if (!data) return 0;
  return data.split('\n').length;
}

module.exports = { logConversion, getConversionCount };
